/* -------- Model zoo -------- */
static Value ai_model_zoo(VM*vm,int n,Value*a){if(n<1||n>4||a[0].t!=VSTR)return vn();char name[64];snprintf(name,sizeof name,"%s",a[0].u.s);if(!strcasecmp(name,"mlp_tiny")||!strcasecmp(name,"mlp.tiny")){int in=n>=2&&a[1].t==VINT?(int)a[1].u.i:16,h=n>=3&&a[2].t==VINT?(int)a[2].u.i:32,o=n>=4&&a[3].t==VINT?(int)a[3].u.i:8;return ai_mlp(vm,3,(Value[]){vi(in),vi(h),vi(o)});}if(!strcasecmp(name,"transformer_tiny")||!strcasecmp(name,"transformer.tiny"))return ai_transformer(vm,3,(Value[]){vi(n>=2&&a[1].t==VINT?a[1].u.i:64),vi(4),vi(256)});if(!strcasecmp(name,"rnn_tiny")||!strcasecmp(name,"rnn.tiny"))return ai_rnn(vm,2,(Value[]){vi(n>=2&&a[1].t==VINT?a[1].u.i:16),vi(64)});if(!strcasecmp(name,"lstm_tiny")||!strcasecmp(name,"lstm.tiny"))return ai_lstm(vm,2,(Value[]){vi(n>=2&&a[1].t==VINT?a[1].u.i:16),vi(64)});if(!strcasecmp(name,"cnn_tiny")||!strcasecmp(name,"cnn.tiny")){Value o=vsobj();stput(o.u.st,"kind",vs("cnn"));stput(o.u.st,"kernel",vi(3));stput(o.u.st,"stride",vi(1));stput(o.u.st,"padding",vi(1));return o;}return vn();}

